#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

template <int BLOCK_SIZE, int TILE_SIZE>
__global__ void matmul_kernel(const float* __restrict__ A, const float* __restrict__ B, float* C, int M, int N, int K) {
    // Shared memory for tiles
    __shared__ float As[BLOCK_SIZE][BLOCK_SIZE];
    __shared__ float Bs[BLOCK_SIZE][BLOCK_SIZE];

    // Thread indices
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Block indices
    int bx = blockIdx.x;
    int by = blockIdx.y;

    // Each thread computes TILE_SIZE x TILE_SIZE elements
    float c[TILE_SIZE][TILE_SIZE] = {{0.0f}};

    // Global row and column indices for the top-left corner of the block
    int row_begin = by * BLOCK_SIZE;
    int col_begin = bx * BLOCK_SIZE;

    // Loop over tiles
    for (int t = 0; t < (K + BLOCK_SIZE - 1) / BLOCK_SIZE; ++t) {
        // Load tile of A
        int a_row = row_begin + ty;
        int a_col = t * BLOCK_SIZE + tx;

        if (a_row < M && a_col < K) {
            As[ty][tx] = A[a_row * K + a_col];
        } else {
            As[ty][tx] = 0.0f;
        }

        // Load tile of B (transposed for coalesced access)
        int b_row = t * BLOCK_SIZE + ty;
        int b_col = col_begin + tx;

        if (b_row < K && b_col < N) {
            Bs[tx][ty] = B[b_row * N + b_col];  // Store transposed
        } else {
            Bs[tx][ty] = 0.0f;
        }

        __syncthreads();

        // Compute partial product (warp-level matrix multiplication)
        #pragma unroll
        for (int k = 0; k < BLOCK_SIZE; ++k) {
            float a_val = As[ty][k];

            // Each thread computes a TILE_SIZE x TILE_SIZE output
            for (int i = 0; i < TILE_SIZE; i++) {
                float b_val = Bs[tx][k + i * BLOCK_SIZE / TILE_SIZE];
                c[i][0] += a_val * b_val;
            }
        }

        __syncthreads();
    }

    // Write results
    for (int i = 0; i < TILE_SIZE; i++) {
        for (int j = 0; j < TILE_SIZE; j++) {
            int row = row_begin + ty + i * BLOCK_SIZE / TILE_SIZE;
            int col = col_begin + tx + j * BLOCK_SIZE / TILE_SIZE;

            if (row < M && col < N) {
                C[row * N + col] = c[i][j];
            }
        }
    }
}

